import copy
from taf.analyzer.aasyslog_throughput.calculator import MinimumTimeIntervalCalculator


class Throughput(object):
    def __init__(self, throughput_data_collection, throughput_filter, throughput_calculators, recorder):
        self._throughput_data_collection = throughput_data_collection
        self._filter = throughput_filter
        self._throughput_calculators = throughput_calculators
        self._time_interval_calculator = MinimumTimeIntervalCalculator()
        self._recorder = recorder

    def analyze(self):
        self.reset()
        self._recorder.start()
        for throughput_data in self._filter.do():
            if throughput_data is None:
                continue
            self._update(throughput_data)
        self._recorder.stop()

    def _update(self, throughput_data):
        old_data = copy.deepcopy(self._throughput_data_collection[throughput_data.device_id])
        if self._throughput_data_collection.update(throughput_data):
            self._recorder.add(throughput_data)
            self._time_interval_calculator.calculate(self._throughput_data_collection, old_data)

            for calculator in self._throughput_calculators:
                calculator.calculate(self._throughput_data_collection)

    def get_result(self):
        return self._throughput_data_collection.result

    def on_analyze(self, log_entry):
        throughput_data = self._filter.on_filter(log_entry)
        if throughput_data is not None:
            self._update(throughput_data)

    def reset(self):
        self._throughput_data_collection.reset()
        for calculator in self._throughput_calculators:
            calculator.reset()
        self._recorder.reset()

    @property
    def recorder(self):
        return self._recorder
